    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos_like(x):
        return isinstance(x, (list, tuple)) and len(x) >= 2 and isinstance(x[0], (int, float)) and isinstance(x[1], (int, float))

    def get_self_pos(obs):
        for k in ("self", "agent", "player", "me", "unit", "avatar"):
            v = obs.get(k)
            if isinstance(v, dict):
