                x = v.get("x")
                y = v.get("y")
                if isinstance(x, (int, float)) and isinstance(y, (int, float)):
                    return [int(x), int(y)]
            elif pos_like(v):
                return [int(v[0]), int(v[1])]

        for k in ("position", "pos", "location", "loc", "xy"):
            v = obs.get(k)
            if pos_like(v):
                return [int(v[0]), int(v[1])]
        return [0, 0]

    def extract_points(v):
        pts = []
        if v is None:
            return pts
        if isinstance(v, dict):
            if pos_like(v.get("pos")):
                pts.append([int(v["pos"][0]), int(v["pos"][1])])
            if pos_like(v.get("position")):
                pts.append([int(v["position"][0]), int(v["position"][1])])
            if pos_like(v.get("loc")):
                pts.append([int(v["loc"][0]), int(v["loc"][1])])
            if "x" in v and "y" in v and isinstance(v["x"], (int, float)) and isinstance(v["y"], (int, float)):
                pts.append([int(v["x"]), int(v["y"])])
            return pts
        if pos_like(v):
            pts.append([int(v[0]), int(v[1])])
            return pts
        if isinstance(v, list):
            for e in v:
                pts.extend(extract_points(e))
        return pts

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def blocked_set(obs):
        blocks = set()
        for k in ("walls", "obstacles", "blocked", "blocks", "map_blocks", "terrain"):
            for p in extract_points(obs.get(k)):
                blocks.add((p[0], p[1]))
        return blocks

