            for p in extract_points(obs.get(k)):
                candidates.append((1, p))

        if not candidates:
            return None

        # Prefer closer, then higher score.
        best = None
        best_val = None
        for score, p in candidates:
            d = manhattan(me, p)
            val = (score * 1000) - d
            if best is None or val > best_val:
                best = p
                best_val = val
        return best

