    blocks = blocked_set(observation)
    target = best_target(me, observation)

    # Fallback directional bias if no target.
    if target is None:
        for k in ("goal", "exit", "center", "home"):
            pts = extract_points(observation.get(k))
            if pts:
                target = pts[0]
                break

    if target is None:
        return [0, 0]

    dx = clamp_step(target[0] - me[0])
    dy = clamp_step(target[1] - me[1])

